def save(path, value):
    target = OUT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n')

def source(id, title, url):
    return dict(id=id, title=title, url=url, checked=CHECKED)

