    monitor_summary=[dict(stage='Before',test='Baseline safety and preparation',when=('Blood count, kidneys/liver, glucose, thyroid, hepatitis tests, PD-L1 and DPD; other checks if indicated.' if combo else 'Blood count, kidneys/liver; hearing/CrCl if indicated. Dental, nutrition and radiation preparation.' if not cet else 'Blood count, kidneys/liver and minerals; allergy review. Dental and radiation preparation.'),basis='NCCP / radiation plan'),dict(stage='During',test='Bloods and symptoms',when=('Blood count, kidneys/liver and glucose each cycle; thyroid every 3–6 weeks. Report immune symptoms.' if combo else 'Blood count, kidneys/liver before each cycle. Review hearing, nerves, intake and radiation symptoms.' if not cet else 'Regular bloods and mineral checks; infusion observation, skin, eyes and radiation review.'),basis='NCCP'),dict(stage='After / response',test='Follow-up and tests',when=('Report immune effects after stopping. Scans, examinations and ongoing tests follow your individual plan.' if combo else 'Continue recovery, dental and swallowing care; scans and tests individually planned.' if not cet else 'Mineral tests monthly for 2 months after last dose. Continue radiation recovery and individual scan plan.'),basis='NCCP / individual plan')]
    summary_phases=[dict(title=p['label'],text=(('Day 1 infusions; fluorouracil over Days 1–4. Four 22-hour or two 48-hour infusions as prescribed.' if p['id']=='combination' else 'Pembrolizumab alone every 3 weeks while appropriate; no automatic 24-month stop.') if combo else p['detail'])) for p in phases]
    d['patient_summary']=dict(template_version=VERSION,purpose=r['purpose'],schedule=short,phases=summary_phases,monitoring=monitor_summary,cycle_expectations=[('Pump changes/disconnection follow the prescribed option. Call early for diarrhoea, mouth pain or chest symptoms.' if combo else 'Radiation has its own appointment calendar; mouth, skin and swallowing effects may build across weeks.'),('Immune symptoms can arise during maintenance or after stopping.' if combo else 'Keep drinking and nutrition support active; seek help before intake or weight falls substantially.')],preparation=['Bring your medicine list, test dates, treatment calendar and actual urgent contacts.'],card_title=('Pembrolizumab + '+('cisplatin' if cis else 'carboplatin')+' + 5-FU' if combo else 'Cetuximab + RT' if cet else 'Weekly cisplatin + RT' if weekly else 'Cisplatin + RT'),card_schedule=short,card_cycle_count=r['count'],card_record_unit='administration' if weekly else 'cycle',card_record_note='Combination cycles only; ongoing pembrolizumab has a separate maintenance record.' if combo else 'Record each received weekly dose; the radiation appointments have a separate calendar.' if weekly else 'Rolling weekly record through the radiation course.' if cet else 'Three planned cisplatin cycles; keep the radiation calendar separately.',card_alert=urgent,summary_checked=CHECKED)

